// Generates each coding agent's command permissions from one list, tools/agent-permissions.json, so Claude Code,
// Codex and Antigravity allow, ask about and refuse the same commands.
//
//   node tools/agent-permissions.cjs                  write .claude/settings.json and .codex/rules/project.rules
//   node tools/agent-permissions.cjs --check          exit 1 if either generated file is out of date (the unit test)
//   node tools/agent-permissions.cjs --antigravity    also merge the allow list into this machine's Antigravity
//
// Antigravity keeps its grants in one global file (ANTIGRAVITY_CONFIG, default ~/.gemini/config/config.json), not in
// the repository, and only an allow list is known there. The merge adds this list's allow entries, removes the ones
// it added earlier and no longer lists (tracked in mynewspaper-agent-permissions.json beside it), backs the file up
// and leaves every other grant alone. It reports existing grants broad enough to cover an ask or deny command, since
// those defeat the rule there; remove them by hand or in Antigravity's settings.
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const source = path.join(__dirname, 'agent-permissions.json');
const claudeFile = path.join(root, '.claude/settings.json');
const codexFile = path.join(root, '.codex/rules/project.rules');
const header = 'Generated by tools/agent-permissions.cjs from tools/agent-permissions.json. Do not edit; regenerate.';

function loadRules() {
    const { rules } = JSON.parse(fs.readFileSync(source, 'utf8'));
    const seen = new Set();
    const entries = [];
    for (const rule of rules) {
        if (!['allow', 'ask', 'deny'].includes(rule.decision)) throw new Error(`Unknown decision '${rule.decision}'`);
        for (const command of rule.commands) {
            const tokens = command.trim().split(/\s+/);
            if (tokens.length === 0 || tokens[0] === '') throw new Error('Empty command');
            if (seen.has(tokens.join(' '))) throw new Error(`Listed twice: ${command}`);
            seen.add(tokens.join(' '));
            entries.push({ decision: rule.decision, why: rule.why, tokens });
            // A repository script can be called as tools/x.sh or ./tools/x.sh.
            if (tokens[0].includes('/') && !tokens[0].startsWith('/') && !tokens[0].startsWith('./')) {
                entries.push({
                    decision: rule.decision,
                    why: rule.why,
                    tokens: ['./' + tokens[0], ...tokens.slice(1)],
                });
            }
        }
    }
    return entries;
}

function claudeSettings(entries) {
    const list = (decision) =>
        entries.filter((e) => e.decision === decision).map((e) => `Bash(${e.tokens.join(' ')}:*)`);
    const settings = {
        $schema: 'https://json.schemastore.org/claude-code-settings.json',
        $comment: header,
        permissions: { allow: list('allow'), ask: list('ask'), deny: list('deny') },
    };
    return JSON.stringify(settings, null, 4) + '\n';
}

function codexRules(entries) {
    const decision = { allow: 'allow', ask: 'prompt', deny: 'forbidden' };
    const quote = (s) => JSON.stringify(s);
    const lines = [
        `# ${header}`,
        '# Loaded only when the project is trusted in Codex. Check: codex execpolicy check --rules <this file> -- <cmd>',
        '',
    ];
    for (const e of entries) {
        lines.push(
            'prefix_rule(',
            `    pattern = [${e.tokens.map(quote).join(', ')}],`,
            `    decision = ${quote(decision[e.decision])},`,
            `    justification = ${quote(e.why)},`,
            `    match = [${quote(e.tokens.join(' '))}],`,
            ')',
            '',
        );
    }
    return lines.join('\n');
}

const escapeToken = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const antigravityEntry = (e) => `command(${e.tokens.map(escapeToken).join(' ')})`;
const unescapeToken = (t) => t.replace(/\\(.)/g, '$1');

function mergeAntigravity(entries) {
    const file = process.env.ANTIGRAVITY_CONFIG || path.join(os.homedir(), '.gemini/config/config.json');
    if (!fs.existsSync(file)) {
        console.log(`Antigravity: ${file} not found; skipped.`);
        return;
    }
    const managedFile = path.join(path.dirname(file), 'mynewspaper-agent-permissions.json');
    const config = JSON.parse(fs.readFileSync(file, 'utf8'));
    const grants = (((config.userSettings ??= {}).globalPermissionGrants ??= {}).allow ??= []);
    const previous = fs.existsSync(managedFile) ? JSON.parse(fs.readFileSync(managedFile, 'utf8')).managed : [];
    const wanted = entries.filter((e) => e.decision === 'allow').map(antigravityEntry);

    const kept = grants.filter((g) => !previous.includes(g) || wanted.includes(g));
    const added = wanted.filter((w) => !kept.includes(w));
    const next = [...kept, ...added];
    const removed = grants.length - kept.length;

    // Grants whose tokens are a prefix of an ask or deny command allow that command in Antigravity.
    const conflicts = [];
    for (const g of next) {
        const m = /^command\((.*)\)$/s.exec(g);
        if (!m) continue;
        const tokens = m[1].trim().split(/\s+/).map(unescapeToken);
        for (const e of entries.filter((x) => x.decision !== 'allow')) {
            if (tokens.length <= e.tokens.length && tokens.every((t, i) => t === e.tokens[i])) {
                conflicts.push(`${g} covers ${e.decision}: ${e.tokens.join(' ')}`);
            }
        }
    }

    if (added.length > 0 || removed > 0) {
        const backup = `${file}.bak`;
        fs.copyFileSync(file, backup);
        fs.chmodSync(backup, 0o600);
        config.userSettings.globalPermissionGrants.allow = next;
        fs.writeFileSync(file, JSON.stringify(config, null, 2));
    }
    fs.writeFileSync(managedFile, JSON.stringify({ $comment: header, managed: wanted }, null, 2) + '\n');
    console.log(`Antigravity: ${added.length} added, ${removed} removed, ${next.length} grants in ${file}.`);
    for (const c of conflicts) console.log(`  warning: ${c}`);
}

function main() {
    const args = new Set(process.argv.slice(2));
    const entries = loadRules();
    const outputs = [
        [claudeFile, claudeSettings(entries)],
        [codexFile, codexRules(entries)],
    ];
    if (args.has('--check')) {
        const stale = outputs.filter(([f, text]) => !fs.existsSync(f) || fs.readFileSync(f, 'utf8') !== text);
        for (const [f] of stale)
            console.error(`Out of date: ${path.relative(root, f)} (run node tools/agent-permissions.cjs)`);
        process.exit(stale.length > 0 ? 1 : 0);
    }
    for (const [f, text] of outputs) {
        fs.mkdirSync(path.dirname(f), { recursive: true });
        fs.writeFileSync(f, text);
        console.log(`Wrote ${path.relative(root, f)}`);
    }
    if (args.has('--antigravity')) mergeAntigravity(entries);
}

if (require.main === module) main();
module.exports = { loadRules, claudeSettings, codexRules, antigravityEntry };
